function sizeLabel(size) {
  switch (size) {
    case 'S':
    case 'M':
      return 'regular';
    case 'L':
      return 'large';
    default:
      return 'unknown';
  }
}
console.log(sizeLabel('S'), sizeLabel('M'), sizeLabel('L'), sizeLabel('XL'));

